/* ---------- Status pill ---------- */
.spl-stage{min-height:44px;justify-content:center}
.spl-pill{background:var(--surface);border-radius:var(--r-pill);box-shadow:var(--shadow);height:40px;display:flex;align-items:center;overflow:hidden;transition:width .6s var(--ease),border-radius .5s var(--ease),height .5s var(--ease)}
.spl-in{display:flex;align-items:center;gap:9px;padding:0 6px 0 14px;height:100%;white-space:nowrap;font-size:13.5px;transition:opacity .2s var(--ease),filter .2s var(--ease)}
.spl-in.out{opacity:0;filter:blur(4px)}
.spl-in .g{display:grid;place-items:center;width:16px;color:var(--fg2)}
.spl-in .m{color:var(--muted);font-variant-numeric:tabular-nums}
.spl-in .end{width:0}
.spl-in .pill{height:28px;margin-left:4px}
.spl.bar .spl-pill{border-radius:16px;height:62px;align-items:flex-start}
.spl.bar .spl-in{height:46px;width:100%;padding:0 16px}
.spl.bar .spl-in .m,.spl.bar .spl-in .pill{margin-left:auto}
.spl.bar .spl-in .end{display:none}
.spl-track{position:absolute;left:16px;right:16px;bottom:13px;height:3px;border-radius:2px;background:var(--line);overflow:hidden;opacity:0;transition:opacity .3s}
.spl.bar .spl-track{opacity:1}
.spl-fill{height:100%;width:0;border-radius:inherit;background:var(--accent);transition:width .8s var(--ease)}
.spl-pill{position:relative}

DM.def('status-pill', (r, c) => {
  const pill = $('.spl-pill', r), box = $('.spl-in', r), root = $('.spl', r);
  pill.insertAdjacentHTML('beforeend', '<div class="spl-track"><div class="spl-fill"></div></div>');
  const fill = $('.spl-fill', r);
  seg($('.seg2', r), v => { root.classList.toggle('bar', v === 'bar'); fit(); });
  /* both variants hug their content; the bar keeps a little extra room for its track */
  function fit(){
    box.style.width = 'max-content'; const w = box.scrollWidth; box.style.width = '';
    pill.style.width = (root.classList.contains('bar') ? Math.max(w + 24, 300) : w) + 'px';
  }
  function set(htmlStr, pct){
    pill.style.width = pill.offsetWidth + 'px';
    box.classList.add('out');
    c.later(180, () => { box.innerHTML = htmlStr; box.classList.remove('out'); fit(); });
    if (pct !== undefined) fill.style.width = pct + '%';
  }
  const think = '<span class="think on"><i></i><i></i><i></i><i></i></span>';
  box.innerHTML = '<span class="g"><span class="dot" style="color:var(--faint)"></span></span><span class="fg2">Ready for a task</span><span class="end"></span>';
  requestAnimationFrame(fit);
  const idle = '<span class="g"><span class="dot" style="color:var(--faint)"></span></span><span class="fg2">Ready for a task</span><span class="end"></span>';
  c.run(async () => { for (;;){
    await c.wait(1100);
    set(`<span class="g" style="color:var(--fg)">${think}</span><span class="shim">Thinking</span><span class="end"></span>`, 8); await c.wait(1800);
    set(`<span class="g" style="color:var(--fg)"><span class="radar"></span></span><span class="shim">Reading Figma frames</span><span class="m n">1 of 4</span><span class="end"></span>`, 22);
    await c.wait(400);
    for (let i = 2; i <= 4; i++){ await c.wait(650); const n = $('.n', box); if (n) swap(n, i + ' of 4'); fill.style.width = (22 + i * 8) + '%'; }
    await c.wait(700);
    set(`<span class="g" style="color:var(--fg)"><span class="spin"></span></span><span class="shim">Editing</span><span class="fchip" style="height:24px"><span class="ft re">TSX</span>PricingCard.tsx</span><span class="end"></span>`, 64); await c.wait(2000);
    set(`<span class="g" style="color:var(--warn)"><span class="dot"></span></span><span>Waiting for your approval</span><button class="pill ink sm">Review</button>`, 72);
    /* waits for Review, and carries on by itself after a while so the loop never stalls */
    await new Promise(res => { c.later(220, () => { const b = $('.pill', box); if (b) b.onclick = res; }); c.later(8000, res); });
    set(`<span class="g" style="color:var(--fg)"><span class="spin"></span></span><span class="shim">Applying 4 changes</span><span class="end"></span>`, 88); await c.wait(1600);
    set(`<span class="g" style="color:var(--ok)">${I('ok')}</span><span>Done</span><span class="m">4 files changed · 18s</span><span class="end"></span>`, 100);
    await c.wait(3200); set(idle, 0);
  } });
});
